package com.savewhy.app;
import org.junit.Test;
import java.util.*;
import org.json.*;
import static org.junit.Assert.*;
public class ImageCardTest {
    private static final String IMAGE=String.join("",Collections.nCopies(64,"a"));
    Card card(){return new Card("image","","Screenshot","Al","Compare price",10,false,Collections.emptyList(),"",IMAGE,Arrays.asList("Alışveriş","İş"),"Kablosuz kulaklık 1500 TL","ready");}
    @Test public void imageNeedsNoUrlAndSearchFindsTagsAndRecognizedText(){Card c=card();assertTrue(c.isImage());assertEquals("",c.url);assertTrue(c.matches("alisveris"));assertTrue(c.matches("kulaklik"));assertTrue(c.visible("Görseller","1500"));assertFalse(new Card("link","https://example.com","Link","Al","Later",0,false,Collections.emptyList()).visible("Görseller",""));}
    @Test public void imageRoundTripAndCopyPreserveAllFields()throws Exception{Card c=card();c.reminderAt=123;c.lastActivityAt=40;Card copy=c.copy();Card restored=CardCodec.decode(CardCodec.encode(Collections.singletonList(copy))).get(0);assertEquals(IMAGE,restored.imageId);assertEquals(c.tags,restored.tags);assertEquals(c.recognizedText,restored.recognizedText);assertEquals("ready",restored.ocrState);assertEquals(123,restored.reminderAt);assertEquals(40,restored.lastActivityAt);}
    @Test public void imageDuplicateAndConflictingIdMergeRetainMedia(){Card c=card();assertEquals(1,CardCodec.merge(Collections.singletonList(c),Collections.singletonList(c.copy())).size());Card link=new Card("image","https://example.com","Link","Al","Later",0,false,Collections.emptyList());List<Card> merged=CardCodec.merge(Collections.singletonList(link),Collections.singletonList(c));assertEquals(2,merged.size());assertNotEquals("image",merged.get(1).id);assertEquals(IMAGE,merged.get(1).imageId);assertEquals(c.tags,merged.get(1).tags);}
    @Test public void tagsTrimAndDeduplicateTurkishText(){assertEquals(Arrays.asList("İş","Tarif"),Card.parseTags(" İş, is, Tarif, ,tarif "));assertThrows(IllegalArgumentException.class,()->Card.parseTags(Collections.nCopies(1,String.join("",Collections.nCopies(41,"x")))));List<String> tooMany=new ArrayList<>();for(int i=0;i<13;i++)tooMany.add("tag"+i);assertThrows(IllegalArgumentException.class,()->Card.parseTags(tooMany));}
    @Test public void malformedImageReferencesAndMixedTypesAreRejected(){assertThrows(IllegalArgumentException.class,()->new Card("i","","Title","Al","Later",0,false,Collections.emptyList(),"","../../bad",Collections.emptyList(),"","none"));assertThrows(IllegalArgumentException.class,()->new Card("i","https://example.com","Title","Al","Later",0,false,Collections.emptyList(),"",IMAGE,Collections.emptyList(),"","none"));}
    @Test public void versionFourLinksMigrateWithoutMedia()throws Exception{JSONObject old=new JSONObject(CardCodec.encode(Collections.singletonList(new Card("link","https://example.com","Link","Al","Later",0,false,Collections.emptyList()))));old.put("version",4);JSONObject c=old.getJSONArray("cards").getJSONObject(0);for(String key:new String[]{"imageId","tags","recognizedText","ocrState"})c.remove(key);Card restored=CardCodec.decode(old.toString()).get(0);assertFalse(restored.isImage());assertTrue(restored.tags.isEmpty());assertEquals("none",restored.ocrState);}
}
